import{_ as d,o as a,c as e,a3 as r}from"./chunks/framework.DxEvSMU4.js";const b=JSON.parse('{"title":"M4 檢索增強生成 (RAG)","description":"","frontmatter":{},"headers":[],"relativePath":"build/m4-retrieval.md","filePath":"build/m4-retrieval.md","lastUpdated":1793014002000}'),i={name:"build/m4-retrieval.md"};function l(o,t,n,h,m,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="m4-檢索增強生成-rag" tabindex="-1">M4 檢索增強生成 (RAG) <a class="header-anchor" href="#m4-檢索增強生成-rag" aria-label="Permalink to &quot;M4 檢索增強生成 (RAG)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境, 有「問自己文件」的需求才讀</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 查無公開的繁體中文嵌入與重排序基準 (含 TAIDE 嵌入模型); pgvector 與 sqlite-vec 授權為訓練資料內資訊, 可能已過時; 向量庫記憶體占用未引用公開實測</li></ul></div><p><strong>結論</strong>: 家庭規模 (數萬至數十萬段落) 下, 向量庫的選擇差異遠小於嵌入模型與文件解析品質的差異, 因此以「備份是否簡單」當作主要選擇依據 (信心: 中高). 嵌入模型的排行榜名次不一定適用繁體中文, 請用自己的 50 題問答實測.</p><p><strong>這一塊在圖上的位置</strong>: VM 入口區的 Docling 與 Qdrant, 嵌入模型跑在推論伺服器. <strong>前置模組</strong>: M1, M2. <strong>完成後的狀態</strong>: 使用者可以在介面中針對自己的文件提問, 回答附上出處.</p><h2 id="m4-1-文件解析" tabindex="-1">M4.1 文件解析 <a class="header-anchor" href="#m4-1-文件解析" aria-label="Permalink to &quot;M4.1 文件解析&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>授權</th><th>特點</th></tr></thead><tbody><tr><td>Docling (IBM)</td><td>MIT</td><td>可在純 CPU 執行, 格式涵蓋最廣; 2026 年中為 v2.111 (Medium 比較文)</td></tr><tr><td>MinerU (OpenDataLab)</td><td>3.1.0 起改為自訂授權: 月活躍使用者超過 1 億或月營收超過 2,000 萬美元須另取商業授權, 線上服務須標示使用 MinerU (docsumo.com)</td><td>中文與表格公認最強; pipeline 後端 (CPU) 在 OmniDocBench 約 86 分, VLM 後端 (GPU) 約 95 分以上</td></tr></tbody></table><p>OmniDocBench 由 MinerU 同一團隊維護, 評測結果須保留一分懷疑. 最小可行做法是先人工把文件轉成乾淨的文字或 Markdown, 再匯入.</p><h2 id="m4-2-嵌入模型-向量庫與重排序" tabindex="-1">M4.2 嵌入模型, 向量庫與重排序 <a class="header-anchor" href="#m4-2-嵌入模型-向量庫與重排序" aria-label="Permalink to &quot;M4.2 嵌入模型, 向量庫與重排序&quot;">​</a></h2><h3 id="嵌入模型" tabindex="-1">嵌入模型 <a class="header-anchor" href="#嵌入模型" aria-label="Permalink to &quot;嵌入模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>MMTEB (多語)</th><th>C-MTEB (中文)</th><th>大小</th><th>來源</th></tr></thead><tbody><tr><td>Qwen3-Embedding-0.6B</td><td>64.33</td><td>66.33</td><td>Ollama 版 639MB</td><td>Qwen 官方 GitHub, morphllm.com</td></tr><tr><td>Qwen3-Embedding-4B</td><td>69.45</td><td>72.27</td><td>權重約 7,671MB (16-bit)</td><td>Qwen 官方, supermemory.ai</td></tr><tr><td>Qwen3-Embedding-8B</td><td>70.58</td><td>73.84</td><td>權重約 14,433MB</td><td>同上</td></tr><tr><td>bge-m3</td><td>59.56</td><td>-</td><td>約 1.2GB; 支援稠密, 稀疏, 多向量</td><td>Qwen 官方比較表, morphllm.com</td></tr><tr><td>EmbeddingGemma-300m</td><td>61.15 (Google 自報)</td><td>-</td><td>622MB (Ollama); 上下文 2,048 token; Gemma 條款</td><td>surrealdb.com, supermemory.ai</td></tr></tbody></table><p>C-MTEB 以簡體中文為主, 無法直接代表繁體中文表現. 一篇高棉語研究 (arXiv 2605.22099) 中 bge-m3 反而勝過 Qwen3-Embedding, 顯示排行榜名次不一定能轉移到特定語言. <strong>更換嵌入模型就必須重建整個向量庫, 不可混用.</strong></p><h3 id="向量庫" tabindex="-1">向量庫 <a class="header-anchor" href="#向量庫" aria-label="Permalink to &quot;向量庫&quot;">​</a></h3><table tabindex="0"><thead><tr><th>資料庫</th><th>授權</th><th>最新版 (來源)</th><th>單機適用性</th></tr></thead><tbody><tr><td>Qdrant</td><td>Apache 2.0</td><td>1.19.2, 2026-10-05 (vdf.ai)</td><td>單一執行檔, 支援量化與混合檢索; 適合標準組合</td></tr><tr><td>pgvector</td><td>PostgreSQL License (待核對)</td><td>-</td><td>已在用 PostgreSQL 者最省事, 備份一併處理</td></tr><tr><td>Chroma</td><td>Apache 2.0</td><td>1.5.9, 2026-05-05</td><td>內嵌式最易上手; 內嵌模式不支援並行寫入 (Actian)</td></tr><tr><td>LanceDB</td><td>Apache 2.0</td><td>0.39.0, 2026-09-17</td><td>內嵌, 以磁碟為主, 適合大於記憶體的資料</td></tr><tr><td>sqlite-vec</td><td>待核對</td><td>-</td><td>單一檔案, 以暴力搜尋 (逐筆比對) 為主, 資料量大時查詢時間會明顯變長; 請用自己的資料實測</td></tr><tr><td>Milvus</td><td>-</td><td>-</td><td>分散式設計, 單機讀者不需要</td></tr></tbody></table><p>各向量庫的記憶體占用差異很大, 但公開實測多半未註明向量維度, 索引類型與參數, 無法互相對照, 因此本手冊不引用. 容量規劃可先算原始向量大小: 筆數 x 維度 x 4 位元組 (float32). 例如 10 萬筆 x 1,024 維 = 409,600,000 位元組, 約 410MB (計算值). 實際占用還會加上索引與中介資料, 請在自己的資料上實測.</p><h3 id="重排序" tabindex="-1">重排序 <a class="header-anchor" href="#重排序" aria-label="Permalink to &quot;重排序&quot;">​</a></h3><p>Qwen 官方提供 Qwen3-Reranker 系列; 繁體中文評測同樣無法確認.</p><h2 id="m4-3-繁體中文-50-題自測法" tabindex="-1">M4.3 繁體中文 50 題自測法 <a class="header-anchor" href="#m4-3-繁體中文-50-題自測法" aria-label="Permalink to &quot;M4.3 繁體中文 50 題自測法&quot;">​</a></h2><p>由於缺乏公開的繁體中文檢索基準, 請依下列步驟自行評測 (信心: 中高):</p><ol><li>從自己的文件中挑 50 個實際會問的問題, 每題記錄「正確答案所在的段落」.</li><li>對兩個候選嵌入模型分別建立向量庫.</li><li>每題檢索前 5 筆段落, 計算「正確段落出現在前 5 筆」的比例 (命中率).</li><li>選命中率較高者; 差距小於 5 個百分點時, 選記憶體較小者.</li><li>把這 50 題併入 M6 的回歸測試集, 之後每次換模型或調整切塊都重跑.</li></ol><h2 id="m4-4-組合建議" tabindex="-1">M4.4 組合建議 <a class="header-anchor" href="#m4-4-組合建議" aria-label="Permalink to &quot;M4.4 組合建議&quot;">​</a></h2><h3 id="最小可行組合" tabindex="-1">最小可行組合 <a class="header-anchor" href="#最小可行組合" aria-label="Permalink to &quot;最小可行組合&quot;">​</a></h3><ul><li>介面內建 RAG (Open WebUI 或 AnythingLLM)</li><li>嵌入模型: Qwen3-Embedding-0.6B 或 bge-m3</li><li>向量庫: 介面內建的 (Chroma 或 pgvector)</li><li>文件先人工轉成乾淨的文字或 Markdown</li><li>額外記憶體約 1 至 2GB (推論)</li></ul><h3 id="進階組合" tabindex="-1">進階組合 <a class="header-anchor" href="#進階組合" aria-label="Permalink to &quot;進階組合&quot;">​</a></h3><p>Docling (CPU) 或 MinerU (有 GPU) 解析 → Qwen3-Embedding-0.6B 或 4B → Qdrant (混合檢索) → Qwen3-Reranker 重排序 → 用 50 至 100 題自建繁體中文測試集評估命中率.</p><h3 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h3><p>RAG 的文件來源就是攻擊面. 只匯入可信資料夾, 對應 OWASP LLM08 與 ASI06 (見 K6.4 節).</p>',26)])])}const p=d(i,[["render",l]]);export{b as __pageData,p as default};
